/*
 * Shape data for <MuscleIcon>. Hand-drawn for Iron Arc (no third-party art).
 * viewBox 0 0 48 48: a front or back silhouette with chunky muscle shapes
 * that stay readable at 24px. Points are [x, y] polygons; the right side of
 * the body is generated by mirroring the left (x → 48 − x).
 */

export type MuscleGroup =
  | "chest"
  | "back"
  | "shoulders"
  | "arms"
  | "biceps"
  | "triceps"
  | "forearms"
  | "legs"
  | "core"
  | "fullBody"
  | "cardio";

type Point = [number, number];
type Poly = Point[];

export const VIEWBOX = "0 0 48 48";

const mirror = (poly: Poly): Poly => poly.map(([x, y]) => [48 - x, y] as Point).reverse();
const both = (poly: Poly): Poly[] => [poly, mirror(poly)];

/** Polygon → SVG path data. */
export const toPath = (poly: Poly) => `M${poly.map(([x, y]) => `${x} ${y}`).join("L")}Z`;

// Silhouette
export const HEAD = { cx: 24, cy: 5, r: 4.2 };
const TORSO: Poly = [
  [19.6, 9.6], [28.4, 9.6], [34, 12], [33.6, 18], [31.4, 23.5], [31.8, 27],
  [16.2, 27], [16.6, 23.5], [14.4, 18], [14, 12],
];
const ARM: Poly = [
  [14, 12], [10.6, 13.4], [9, 20], [7.6, 27.5], [7.2, 31.6], [10.6, 31.9], [11.8, 27.5], [13.6, 21.5], [14.4, 18],
];
const LEG: Poly = [[16.2, 27], [23.4, 27], [23.1, 36], [22.6, 46.5], [18.2, 46.5], [17, 36]];

export const SILHOUETTE: Poly[] = [TORSO, ...both(ARM), ...both(LEG)];

// Muscles
const PEC: Poly = [[23.2, 11.8], [18, 11.6], [15.4, 13.4], [16, 17.6], [19.8, 18.8], [23.2, 17.8]];
const DELT: Poly = [[16.4, 10], [10.4, 11.9], [8.7, 18.8], [13.9, 17.2], [16.4, 13.8]];
const BICEP: Poly = [[10.6, 16.2], [9.1, 23.4], [13.5, 23.6], [14.5, 17.2]];
const FOREARM: Poly = [[8.9, 24.2], [7.4, 31.4], [11, 31.6], [13.3, 24.4]];
const OBLIQUE: Poly = [[16.4, 18.8], [20.2, 19.4], [20.2, 26], [17.2, 25.4]];
const QUAD: Poly = [[16.8, 28.2], [23.1, 28.2], [22.9, 35.4], [18, 35.4]];
const SHIN: Poly = [[17.9, 37.4], [22.8, 37.4], [22.4, 44.6], [18.5, 44.6]];
/** Back view: the whole back of the upper arm. */
const TRICEP: Poly = [[14.6, 13.4], [10.9, 13.6], [9.2, 20.4], [9.4, 23.4], [13.4, 23.4], [14.5, 18.6]];
const TRAPS: Poly = [[24, 9], [29.6, 11.4], [24, 17.6], [18.4, 11.4]];
const LAT: Poly = [[15.2, 13.6], [21.2, 18.2], [22.8, 25.8], [18, 25.4], [16, 19.8]];
const HAMSTRING: Poly = [[16.8, 28.2], [23.1, 28.2], [22.9, 35.4], [18, 35.4]];
const CALF: Poly = [[17.9, 37.2], [22.8, 37.2], [22.4, 42.4], [18.4, 42.4]];

/** Six ab blocks, two columns either side of the midline. */
const ABS: Poly[] = [18.8, 21.4, 24].flatMap((y) => {
  const block: Poly = [[20.9, y], [23.4, y], [23.4, y + 2.1], [20.9, y + 2.1]];
  return both(block);
});

export type IconSpec =
  | { kind: "body"; view: "front" | "back"; muscles: Poly[]; whole?: boolean }
  | { kind: "cardio" };

export const MUSCLE_ICONS: Record<MuscleGroup, IconSpec> = {
  chest: { kind: "body", view: "front", muscles: both(PEC) },
  back: { kind: "body", view: "back", muscles: [TRAPS, ...both(LAT), ...both(DELT)] },
  shoulders: { kind: "body", view: "front", muscles: both(DELT) },
  arms: { kind: "body", view: "front", muscles: [...both(BICEP), ...both(FOREARM)] },
  biceps: { kind: "body", view: "front", muscles: both(BICEP) },
  triceps: { kind: "body", view: "back", muscles: both(TRICEP) },
  forearms: { kind: "body", view: "front", muscles: both(FOREARM) },
  legs: { kind: "body", view: "front", muscles: [...both(QUAD), ...both(SHIN)] },
  core: { kind: "body", view: "front", muscles: [...ABS, ...both(OBLIQUE)] },
  fullBody: { kind: "body", view: "front", muscles: [], whole: true },
  cardio: { kind: "cardio" },
};

/** Back-view legs: hamstrings + calves. */
const POSTERIOR_LEGS: Poly[] = [...both(HAMSTRING), ...both(CALF)];

/** Analytics' muscle groups (utils/analytics MAIN_GROUPS; "Abs" shows as Core). */
export type BodyMapGroup = "Chest" | "Back" | "Shoulders" | "Biceps" | "Triceps" | "Forearms" | "Legs" | "Abs";

/**
 * Body map (Analytics → Muscle balance): which shapes belong to each group,
 * front and back. Listed in paint order (later shapes draw on top).
 */
export const BODY_MAP: Record<"front" | "back", { group: BodyMapGroup; shapes: string[] }[]> = {
  front: [
    { group: "Legs", shapes: [...both(QUAD), ...both(SHIN)].map(toPath) },
    { group: "Abs", shapes: [...ABS, ...both(OBLIQUE)].map(toPath) },
    { group: "Biceps", shapes: both(BICEP).map(toPath) },
    { group: "Forearms", shapes: both(FOREARM).map(toPath) },
    { group: "Chest", shapes: both(PEC).map(toPath) },
    { group: "Shoulders", shapes: both(DELT).map(toPath) },
  ],
  back: [
    { group: "Legs", shapes: POSTERIOR_LEGS.map(toPath) },
    { group: "Back", shapes: [TRAPS, ...both(LAT)].map(toPath) },
    { group: "Triceps", shapes: both(TRICEP).map(toPath) },
    { group: "Forearms", shapes: both(FOREARM).map(toPath) },
    { group: "Shoulders", shapes: both(DELT).map(toPath) },
  ],
};

export const HEART_PATH =
  "M24 41C11 32 5.5 24 8 17C10 11.5 17.5 9.5 24 15.5C30.5 9.5 38 11.5 40 17C42.5 24 37 32 24 41Z";
export const PULSE_POINTS = "9,25 17,25 20,19 24,31 27.5,22 30,25 39,25";

/** Backend/app category → icon group. Unknown categories fall back to full body. */
export function muscleGroupForCategory(category: string | null | undefined): MuscleGroup {
  switch ((category ?? "").toLowerCase()) {
    case "chest":
      return "chest";
    case "back":
      return "back";
    case "shoulders":
      return "shoulders";
    case "arms":
      return "arms";
    case "biceps":
      return "biceps";
    case "triceps":
      return "triceps";
    case "forearms":
      return "forearms";
    case "legs":
      return "legs";
    case "abs":
    case "core":
      return "core";
    case "cardio":
      return "cardio";
    default:
      return "fullBody";
  }
}
